import csv,sys
sys.path.insert(0,'scripts')
import honors_match as hm
D='G:/My Drive/00_Primary_Storage_Drive/02_SPORTS/Football/PP_Recruiting/_exports/honors/'
raw=list(csv.DictReader(open(D+'honors_2023_2025_raw.csv',encoding='utf-8')))
for y in (2023,2024,2025):
    sr=[(i,r) for i,r in enumerate(raw,start=2) if int(r['season'])==y]
    pos={hm.norm_name(r['player']) for i,r in sr if hm.keep_honor(r['position'],False) and not hm.ALL_PURPOSE.search(r['position'])}
    for i,r in sr:
        if hm.RETURN_ANY.search(r['position']) and not hm.SPECIALIST.match(r['position'].strip()):
            n=hm.norm_name(r['player']); 
            st='DROP-rr' if hm.return_role(y,r) else ('KEPT' if hm.keep_honor(r['position'],n in pos) else 'dropped')
            if st!='dropped': print(y,i,st,r['source'],r['player'],'|',r['position'],'|',r['selectors'],r['level'])
# specialist-heading rows mentioning all-purpose? 
for i,r in enumerate(raw,start=2):
    if hm.SPECIALIST.match(r['position'].strip()) and hm.ALL_PURPOSE.search(r['position']): print('spec+AP',i,r['player'],r['position'])
EOF
